// A: Numero di buchi
float numHoles = max(floor(A), 1.0); 

// Calcoliamo l'offset per mantenere la figura perfettamente centrata
float offset_u = (numHoles - 1.0) / 2.0;

// Inizializzazione con un valore di distanza fuori scala
float d_final = 10000.0; 

// "Inganniamo" l'auto-formattatore del programma usando int(0.0) e int(20.0). 
// In questo modo la GPU riceve i dati esatti senza errori di conversione.
for(int k = int(0.0); k < int(20.0); k++) {

    // Riconvertiamo a float in sicurezza per la matematica spaziale
    float fk = float(k);

    if(fk < numHoles) { 
        // Centro sull'asse X per questo specifico anello
        float cx = (fk - offset_u) * max(D, 0.1);

        // Coordinate locali
        vec3 p_ring = vec3(p.x - cx, p.y, p.z);

        // Costruzione del singolo toro (buco)
        float d_ring = length(vec2(length(p_ring.xy) - B, p_ring.z)) - C;

        // Uso int(0.0) qui per lo stesso motivo, per evitare errori sul ==
        if(k == int(0.0)) {
            d_final = d_ring; 
        } else {
            d_final = -smax(-d_final, -d_ring, max(E, 0.01));
        }
    }
}

return d_final;
